            "chunk_id": "ba3c865ac4a1",
            "decision": "keep",
            "confidence": 0.95,
            "knowledge_value": "high",
            "reason": "段落包含大量可沉淀的题材知识，如精酿啤酒的原料标准、工艺特点、风格分类、规模定义、市场数据、消费趋势、产品创新等，这些内容具有稳定性和通用性，适合作为知识候选抽取。",
            "knowledge_spans": [
                {
                    "text": "仅使用麦芽、啤酒花、酵母和水四类原料，禁用玉米/淀粉等替代物，确保风味纯粹。",
                    "role": "原料标准",
                    "stability": "high"
                },
                {
                    "text": "部分产品添加百花蜜、陈皮、茶（如毛尖）等天然成分，融合本土风味。",
                    "role": "辅料创新",
                    "stability": "medium"
                },
                {
                    "text": "发酵时间≥1个月（工业啤酒仅7天），充分释放麦芽香气与复杂层次。",
                    "role": "发酵工艺",
                    "stability": "high"
                },
                {
                    "text": "涵盖IPA（印度淡色艾尔）、世涛（Stout）、果啤、酸啤等超100种风格。",
                    "role": "风格分类",
                    "stability": "high"
                },
                {
                    "text": "年产量＜600万桶（约70万吨），非精酿资本持股≤25%，保持酿造自主权。",
                    "role": "规模定义",
                    "stability": "high"
                },
                {
                    "text": "2025年中国精酿市场规模预计突破1300亿元，渗透率从5%升至17.2%，占啤酒行业利润额18%（销量仅4%）。",
                    "role": "市场规模数据",
                    "stability": "medium"
                },
                {
                    "text": "90后/00后占比超60%，女性消费者增速显著（线上男女比例4:1→3:1）。",
                    "role": "消费群体特征",
                    "stability": "medium"
                },
                {
                    "text": "32.85%消费者优先考虑口味，51.94%重视品质，愿为溢价买单（精酿单价12-20元/330ml vs 工业啤酒5-6元）。",
                    "role": "消费偏好",
                    "stability": "medium"
                },
                {
                    "text": "无酒精精酿（如新零品牌）、低醇果味精酿受女性及健康人群追捧。",
                    "role": "健康化趋势",
                    "stability": "medium"
                },
                {
                    "text": "青岛“藤椒赛松”“西柚酸啤”融入本地食材；重庆啤酒“乌苏大红袍”茶啤创新。",
                    "role": "地域融合案例",
                    "stability": "low"
                },
                {
                    "text": "广药集团“凌爽草本精酿”主打中药配方，降低痛风风险。",
                    "role": "健康概念产品",
                    "stability": "low"
                },
                {
                    "text": "海底捞精酿单价降至7元/瓶（京东好评率98%），蜜雪冰城福鹿家推6.6元/杯平价精酿。",
                    "role": "价格策略案例",
                    "stability": "low"
                },
                {
                    "text": "餐饮（海底捞）、零售（盒马）、茶饮（蜜雪冰城）借供应链优势切入市场。",
                    "role": "跨界布局趋势",
                    "stability": "medium"
                }
            ],
            "event_residue": "",
            "drop_target": "noise"
        }
    ]
}
